'use strict';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',tasks:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 9 2 2 4-4M8 16h8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',chats:'<path d="M21 11a8 8 0 0 1-8 8H7l-4 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4zM7 9h10M7 13h6"/>',team:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6m1 5a4 4 0 0 1 3 4v2"/>',notifications:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4"/>',settings:'<path d="m12 3 2 3 4-1 1 4 3 3-3 3-1 4-4-1-2 3-2-3-4 1-1-4-3-3 3-3 1-4 4 1z"/><circle cx="12" cy="12" r="3"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',logout:'<path d="M9 3H4v18h5m5-14 5 5-5 5M8 12h11"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',check:'<path d="m5 12 4 4L19 6"/>',paper:'<path d="m8 15 8-8a3 3 0 0 1 4 4l-10 10a5 5 0 0 1-7-7L14 3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const ic=k=>`<span class="ico"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.tasks}</svg></span>`;
const state={user:null,csrf:'',tasks:[],users:[],events:[],rooms:[],notifications:[],roles:[],metrics:{users:[]},page:'dashboard',taskView:'kanban',calView:'month',calDate:new Date(),room:null,days:30,filters:{},push_key:'',smtp_ready:false};
const names={dashboard:'Visão geral',tasks:'Tarefas',calendar:'Calendário',chats:'Conversas',team:'Equipe',notifications:'Notificações',settings:'Configurações'};
const statusNames={pending:'Pendente',progress:'Em andamento',approval:'Em aprovação',done:'Concluída'};
const priorityNames={low:'Baixa',normal:'Normal',high:'Alta',urgent:'Urgente'};
const can=p=>!!state.user&&(state.user.master||state.user.permissions.includes(p));
const user=id=>state.users.find(u=>u.id===id)||{name:'Usuário',id};
const initials=n=>String(n).split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const avatar=(u,extra='')=>u.photo?`<img data-story-avatar="${esc(u.id||'')}" class="avatar ${extra} ${(state.stories||[]).some(s=>s.user_id===u.id&&new Date(s.expires)>new Date())?'story-ring':''}" src="/files/${esc(u.photo)}" alt="Foto de ${esc(u.name)}">`:`<span data-story-avatar="${esc(u.id||'')}" class="avatar ${extra} ${(state.stories||[]).some(s=>s.user_id===u.id&&new Date(s.expires)>new Date())?'story-ring':''}">${esc(initials(u.name))}</span>`;
const fmt=(v,opt={day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})=>v?new Intl.DateTimeFormat('pt-BR',{...opt,timeZone:'America/Sao_Paulo'}).format(new Date(v)):'Sem prazo';
const localDate=v=>new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const inputDate=v=>v?`${localDate(v)}T${new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v))}`:'';
const datePayload=v=>v?v+'-03:00':null;
const today=()=>localDate(new Date());
const late=t=>t.status!=='done'&&t.due&&new Date(t.due)<new Date();
function toast(text){const el=$('#toast');el.textContent=text;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4000)}
async function request(path,{method='GET',data}={}){if(method!=='GET'&&!navigator.onLine)throw Error('Sem conexão. A alteração não foi enviada.');const r=await fetch('/api'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:data===undefined?undefined:JSON.stringify(data)});const json=await r.json();if(!r.ok){if(r.status===401&&state.user){logoutLocal();}throw Error(json.error||'Falha na solicitação.')}return json}
async function load(){const jobs=[['users','/users',true],['tasks','/tasks',can('tasks')],['events','/events',can('calendar')],['rooms','/rooms',can('chats')],['notifications','/notifications',can('notifications')],['metrics','/metrics?days='+state.days,can('dashboard')],['roles','/roles',can('user_manage')]];const results=await Promise.allSettled(jobs.map(async([key,path,allowed])=>{if(allowed)state[key]=await request(path);else if(key!=='metrics')state[key]=[];}));const errors=results.filter(r=>r.status==='rejected');if(errors.length)throw errors[0].reason}
let source;
function connectLive(){if(source)source.close();source=new EventSource('/api/stream');let pending=false;source.addEventListener('refresh',()=>{if(pending)return;pending=true;setTimeout(async()=>{try{await load();if(!$('#modal-root').children.length){if(state.page==='chats')await refreshMessages();else renderContent();}updateBadge();}catch(e){if(state.user)console.warn('Atualização temporariamente indisponível');}finally{pending=false}},250)});}
function logoutLocal(){state.user=null;if(source)source.close();$('#modal-root').innerHTML='';loginScreen()}
async function bootstrap(){try{const r=await request('/me');Object.assign(state,r);await load();route();connectLive()}catch{loginScreen()}}
function developed(){return `<a class="developed-by" href="https://njamarketing.com.br/" target="_blank" rel="noopener noreferrer"><span>Desenvolvido por</span><img src="/nja-logo-original.png" alt="NJA Consultoria e Marketing"></a>`}
function brand(){return `<div class="brand"><img src="/nja-symbol.png" alt=""><div>NJA System<span>SISTEMA DO NINJA</span></div></div>`}
function loginScreen(mode='login'){const reset=new URLSearchParams(location.search).get('reset');if(reset)mode='reset';$('#app').innerHTML=`<div class="login"><section class="login-art">${brand()}<div class="art-copy"><img class="ninja" src="/nja-symbol.png" alt="Símbolo do Sistema do Ninja"><div class="label">MENOS RUÍDO. MAIS RESULTADO.</div><h1>Sua equipe.<br>Seu ritmo.<br><em>Tudo conectado.</em></h1><p>Um espaço para organizar o trabalho, conectar pessoas e transformar planos em entregas.</p></div><footer>${developed()}</footer></section><section class="login-form"><form id="loginform"><div class="label">BEM-VINDO AO SEU ESPAÇO</div><h2>${mode==='login'?'Vamos ao trabalho.':mode==='reset'?'Crie uma nova senha.':'Recupere seu acesso.'}</h2><p>${mode==='login'?'Entre com sua conta da equipe NJA.':mode==='reset'?'Escolha uma senha com pelo menos 10 caracteres.':'Enviaremos um link para seu e-mail cadastrado.'}</p>${mode!=='reset'?field('E-mail','email','email','',true):''}${mode!=='recover'?field('Senha','password','password','',true,'Mínimo 10 caracteres para uma nova senha.'):''}${mode==='reset'?field('Confirme a nova senha','confirmation','password','',true):''}${mode==='login'?'<button type="button" class="forgot" id="forgot">Esqueci minha senha</button>':''}<div class="form-error" id="loginerror" role="alert"></div><button class="btn lime full" type="submit">${mode==='login'?'Entrar no sistema':mode==='reset'?'Redefinir senha':'Enviar instruções'} ${ic('arrow')}</button>${mode!=='login'?'<button type="button" class="full textlink" id="backlogin">Voltar ao login</button>':''}<p class="tiny muted" style="margin-top:25px">Acesso exclusivo para usuários cadastrados pelo administrador.</p></form><div class="login-credit">${developed()}</div></section></div>`;
$('#forgot')?.addEventListener('click',()=>loginScreen('recover'));$('#backlogin')?.addEventListener('click',()=>{history.replaceState(null,'','/');loginScreen()});$('#loginform').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;$('#loginerror').textContent='';try{const data=Object.fromEntries(new FormData(e.target));if(mode==='login'){const r=await request('/login',{method:'POST',data});Object.assign(state,r);const me=await request('/me');Object.assign(state,me);await load();route();connectLive();}else{if(mode==='reset')data.token=reset;const r=await request(mode==='reset'?'/reset':'/recover',{method:'POST',data});toast(r.message);if(mode==='reset'){history.replaceState(null,'','/');loginScreen()}}}catch(e){$('#loginerror').textContent=e.message}finally{b.disabled=false}};}
function field(label,name,type='text',value='',required=false,hint=''){return `<label class="field">${label}<input type="${type}" ${type==='number'?'step="any"':''} name="${name}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'autocomplete="'+(name==='current'?'current-password':'new-password')+'" maxlength="256"':type==='email'?'autocomplete="email" maxlength="254"':''}>${hint?`<span class="hint">${hint}</span>`:''}</label>`}
function selectField(label,name,options,value,multiple=false){return `<label class="field">${label}<select name="${name}" ${multiple?'multiple':''}>${options.map(([v,t])=>`<option value="${esc(v)}" ${(multiple?(value||[]).includes(v):v===value)?'selected':''}>${esc(t)}</option>`).join('')}</select>${multiple?'<span class="hint">No computador, use Ctrl/Cmd para selecionar vários.</span>':''}</label>`}
function textarea(label,name,value=''){return `<label class="field">${label}<textarea name="${name}" maxlength="10000">${esc(value)}</textarea></label>`}
function navAllowed(p){return p==='settings'||can(p)}
function route(){state.page=location.hash.slice(1).split(':')[0]||'dashboard';if(!names[state.page]||!navAllowed(state.page))state.page=Object.keys(names).find(navAllowed)||'settings';if(state.page==='chats'&&location.hash.includes(':'))state.room=location.hash.split(':')[1];shell();const deep=location.hash.split(':')[1];if(state.page==='tasks'&&deep)taskDetail(deep).catch(e=>toast(e.message))}
window.addEventListener('hashchange',()=>{if(state.user)route()});
function shell(){$('#app').innerHTML=`<aside class="sidebar" id="sidebar"><button type="button" class="sidebar-close" aria-label="Fechar menu">× Fechar</button>${brand()}<div class="label">ESPAÇO DE TRABALHO</div><nav class="nav">${Object.keys(names).filter(navAllowed).map(p=>`<a href="#${p}" class="${p===state.page?'active':''}">${ic(p)}${names[p]}${p==='notifications'?'<span id="navbadge"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom">${developed()}<div class="mini-banner"><strong>Leve a NJA com você.</strong><p>Seu espaço de trabalho, também no celular.</p><button class="btn lime small full" id="install-side">Instalar aplicativo ${ic('arrow')}</button></div><div class="account">${avatar(state.user)}<div class="grow"><strong>${esc(state.user.name.split(' ').slice(0,2).join(' '))}</strong><small>${state.user.master?'Administrador master':esc(state.user.title||'Colaborador')}</small></div><button id="logout" aria-label="Sair">${ic('logout')}</button></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu iconbtn" id="menu" aria-label="Abrir menu">${ic('menu')}</button><div class="breadcrumb">Workspace <strong>/ &nbsp; ${names[state.page]}</strong></div><div class="top-actions"><span class="tiny muted">${fmt(new Date(),{day:'2-digit',month:'long'})}</span><a class="iconbtn" href="#notifications" aria-label="Notificações">${ic('notifications')}<span id="topbadge"></span></a>${avatar(state.user)}</div></header><div class="content" id="content"></div><footer class="system-credit">${developed()}</footer></main>`;$('#logout').onclick=async()=>{try{await request('/push',{method:'DELETE',data:{}});await request('/logout',{method:'POST',data:{}});history.replaceState(null,'','/');logoutLocal()}catch(e){toast(e.message)}};$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#install-side').onclick=installModal;renderContent();updateBadge()}
function updateBadge(){const n=state.notifications.filter(n=>!n.seen).length;for(const s of ['#navbadge','#topbadge'])if($(s))$(s).innerHTML=n?`<span class="badgecount">${n}</span>`:''}
function pagehead(title,desc,action=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function renderContent(){if(!state.user)return;const html={dashboard:dashboard,tasks:tasksPage,calendar:calendarPage,chats:chatsPage,team:teamPage,notifications:notificationsPage,settings:settingsPage}[state.page]();$('#content').innerHTML=html;bindContent()}
function dashboard(){const mine=state.user.master?state.tasks:state.tasks.filter(t=>t.owner===state.user.id);const open=mine.filter(t=>t.status!=='done');const overdue=open.filter(late);const dueToday=open.filter(t=>t.due&&localDate(t.due)===today());const done=mine.filter(t=>t.status==='done');const upcoming=expandedEvents(new Date(),new Date(Date.now()+7*864e5)).slice(0,4);return pagehead('Seu próximo passo começa aqui.','Organize as prioridades e acompanhe o ritmo da equipe.',can('task_create')?`<button class="btn" data-action="newtask">${ic('plus')} Nova tarefa</button>`:'')+`<div class="welcome"><div><span class="label">NJA SYSTEM / ${state.user.master?'VISÃO DA EQUIPE':'SEU PAINEL'}</span><h2>Bom trabalho, ${esc(state.user.name.split(' ')[0])}.</h2><p>${overdue.length?`Há ${overdue.length} tarefa(s) com prazo vencido. Vamos organizar as próximas entregas?`:'Um lugar para manter cada entrega no caminho certo.'}</p><a href="#tasks" class="btn lime small">Ver minhas tarefas ${ic('arrow')}</a></div><img src="/nja-symbol.png" class="mark" alt=""></div><div class="stats">${[['Tarefas em aberto',open.length,'Todas as tarefas visíveis','tasks'],['Para hoje',dueToday.length,'Prazo na data de hoje','calendar'],['Concluídas',done.length,'Estado atual · todo o histórico','check'],['Atrasadas',overdue.length,'Prazo vencido e não concluídas','clock']].map(([label,n,hint,icon],i)=>`<div class="stat ${i===3?'alert':''}"><div class="stat-top">${label}${ic(icon)}</div><strong>${n}</strong><small>${hint}</small></div>`).join('')}</div><div class="grid2"><section class="panel"><div class="panelhead"><h2>Prioridades da equipe</h2><a href="#tasks" class="textlink">Ver todas ↗</a></div>${open.sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,5).map(t=>`<button class="row full" data-task="${t.id}"><span class="checkdot"></span><div class="grow" style="text-align:left"><strong>${esc(t.title)}</strong><small>${esc(t.project||'Sem projeto')} · ${esc(user(t.owner).name)}</small></div><span class="pill ${late(t)?'late':t.status}">${late(t)?'Atrasada':statusNames[t.status]}</span></button>`).join('')||empty('Ainda não há tarefas em aberto.','Crie a primeira tarefa para começar.')}</section><section class="panel"><div class="panelhead"><h2>Na sua agenda</h2><a href="#calendar" class="textlink">Abrir calendário ↗</a></div>${upcoming.map(e=>`<button class="row full" data-event="${e.id}"><div class="eventdate">${fmt(e.start,{day:'2-digit'})}<small>${fmt(e.start,{month:'short'})}</small></div><div class="grow" style="text-align:left"><strong>${esc(e.title)}</strong><small>${fmt(e.start,{hour:'2-digit',minute:'2-digit'})} · ${esc(e.location||'Sem local definido')}</small></div>${ic('arrow')}</button>`).join('')||empty('Sua agenda está livre.','Cadastre compromissos e configure os lembretes.')}</section></div><section class="panel" style="margin-top:22px"><div class="panelhead"><h2>Ritmo de entregas</h2><div class="inline-actions"><select id="metricdays"><option value="7" ${state.days===7?'selected':''}>Últimos 7 dias</option><option value="30" ${state.days===30?'selected':''}>Últimos 30 dias</option><option value="90" ${state.days===90?'selected':''}>Últimos 90 dias</option></select>${state.user.master?'<input id="metricsearch" class="search" placeholder="Filtrar pessoa ou área" aria-label="Filtrar indicadores">':''}</div></div><p class="tiny muted">${esc(state.metrics.criterion||'')}</p><div id="metricrows">${metricRows(state.metrics.users)}</div></section>`}
function metricRows(rows){return rows.map(m=>`<div class="row">${avatar(user(m.id))}<div class="grow"><strong>${esc(m.name)}</strong><small>${esc(m.area||'Área não definida')}</small></div><div style="width:110px"><div class="tiny muted" style="margin-bottom:8px">${m.done}/${m.total} resolvidas · ${m.percent}%</div><div class="progress-track"><span style="--progress:${m.percent}%"></span></div></div></div>`).join('')||empty('Nenhuma tarefa no período selecionado.')}
function empty(a,b=''){return `<div class="empty">${a}${b?'<br><span class="tiny">'+b+'</span>':''}</div>`}
function filteredTasks(){const f=state.filters;return state.tasks.filter(t=>(!f.search||[t.title,t.project,t.description].join(' ').toLowerCase().includes(f.search.toLowerCase()))&&(!f.owner||t.owner===f.owner)&&(!f.project||t.project===f.project)&&(!f.priority||t.priority===f.priority)&&(!f.status||(f.status==='late'?late(t):t.status===f.status))&&(!f.due||(f.due==='today'?t.due&&localDate(t.due)===today():f.due==='week'?t.due&&new Date(t.due)>=new Date()&&new Date(t.due)<=new Date(Date.now()+7*864e5):!t.due)))}
function taskResults(){const ts=filteredTasks();return state.taskView==='kanban'?`<div class="kanban">${Object.entries(statusNames).map(([s,n])=>`<section class="column" data-drop="${s}"><div class="columnhead"><span>${n}<small>${ts.filter(t=>t.status===s).length}</small></span><button data-action="newtask" aria-label="Nova tarefa">+</button></div>${ts.filter(t=>t.status===s).map(t=>`<button class="taskcard" data-task="${t.id}" draggable="true" data-drag="${t.id}"><span class="pill ${t.priority}">${priorityNames[t.priority]}</span>${late(t)?'<span class="pill late">Atrasada</span>':''}<div class="project">${esc(t.project||'Geral')}${t.parent?' · Subtarefa':''}</div><h3>${esc(t.title)}</h3><div class="card-bottom"><small>${ic('calendar')} ${t.due?fmt(t.due,{day:'2-digit',month:'short'}):'Sem prazo'}</small>${avatar(user(t.owner))}</div></button>`).join('')||empty('Sem tarefas')}</section>`).join('')}</div>`:`<div class="tablewrap"><table><thead><tr><th>Tarefa / projeto</th><th>Responsável</th><th>Prioridade</th><th>Prazo</th><th>Estado</th></tr></thead><tbody>${ts.map(t=>`<tr><td><button data-task="${t.id}"><strong>${esc(t.title)}</strong><div class="tiny muted">${esc(t.project)}</div></button></td><td>${esc(user(t.owner).name)}</td><td><span class="pill ${t.priority}">${priorityNames[t.priority]}</span></td><td>${fmt(t.due)}</td><td><span class="pill ${late(t)?'late':t.status}">${late(t)?'Atrasada':statusNames[t.status]}</span></td></tr>`).join('')}</tbody></table>${!ts.length?empty('Nenhuma tarefa encontrada.'):''}</div>`}
function filterSelect(name,label,opts){return `<select data-filter="${name}" aria-label="${label}"><option value="">${label}</option>${opts.map(([id,n])=>`<option value="${esc(id)}" ${state.filters[name]===id?'selected':''}>${esc(n)}</option>`).join('')}</select>`}
function tasksPage(){return pagehead('Cada tarefa, um passo à frente.','Organize, priorize e acompanhe as entregas.',can('task_create')?`<button class="btn" data-action="newtask">${ic('plus')} Nova tarefa</button>`:'')+`<div class="filters"><input data-filter="search" placeholder="Buscar tarefa ou projeto" value="${esc(state.filters.search||'')}" aria-label="Buscar tarefas">${filterSelect('owner','Responsável',state.users.filter(u=>u.active).map(u=>[u.id,u.name]))}${filterSelect('project','Projeto',[...new Set(state.tasks.map(t=>t.project).filter(Boolean))].map(p=>[p,p]))}${filterSelect('priority','Prioridade',Object.entries(priorityNames))}${filterSelect('status','Estado',[...Object.entries(statusNames),['late','Atrasadas']])}${filterSelect('due','Prazo',[['today','Hoje'],['week','Próximos 7 dias'],['none','Sem prazo']])}<div class="viewtoggle"><button data-view="kanban" class="${state.taskView==='kanban'?'selected':''}">Kanban</button><button data-view="list" class="${state.taskView==='list'?'selected':''}">Lista</button></div></div><div id="taskresults">${taskResults()}</div>`}
function expandedEvents(after,before){const results=[];for(const e of state.events){const start=new Date(e.start);const duration=new Date(e.end)-start;let cursor=new Date(start),i=0;const until=e.until_date?new Date(e.until_date):start;while(cursor<=before&&cursor<=until&&i<10000){if(new Date(+cursor+duration)>=after)results.push({...e,start:cursor.toISOString(),end:new Date(+cursor+duration).toISOString()});i++;if(e.recurrence==='none')break;const base=inputDate(e.start);let datePart=base.slice(0,10);const [year,month,day]=datePart.split('-').map(Number);const wall=new Date(Date.UTC(year,month-1,day));if(e.recurrence==='daily')wall.setUTCDate(wall.getUTCDate()+i);else if(e.recurrence==='weekly')wall.setUTCDate(wall.getUTCDate()+7*i);else{wall.setUTCDate(1);wall.setUTCMonth(wall.getUTCMonth()+i);wall.setUTCDate(Math.min(day,new Date(Date.UTC(wall.getUTCFullYear(),wall.getUTCMonth()+1,0)).getUTCDate()))}cursor=new Date(wall.toISOString().slice(0,10)+'T'+base.slice(11)+'-03:00')}}return results.sort((a,b)=>new Date(a.start)-new Date(b.start))}
function calendarPage(){const d=state.calDate;const first=new Date(d.getFullYear(),d.getMonth(),1,12);const begin=new Date(first);begin.setDate(begin.getDate()-begin.getDay());const end=new Date(begin);end.setDate(end.getDate()+42);const events=expandedEvents(begin,end);const view=state.calView;const title=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(d);let body='';if(view==='month'){body=`<div class="calendar"><div class="calhead">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(x=>`<div>${x}</div>`).join('')}</div><div class="calgrid">${Array.from({length:42},(_,i)=>{const dt=new Date(begin);dt.setDate(dt.getDate()+i);const key=localDate(dt);return `<div data-open-day="${key}" tabindex="0" aria-label="Adicionar compromisso em ${key}" class="calcell ${dt.getMonth()!==d.getMonth()?'outside':''} ${key===today()?'today':''}"><button class="daynum" data-newdate="${key}" aria-label="Novo compromisso em ${key}">${dt.getDate()}</button>${events.filter(e=>localDate(e.start)===key).map(e=>`<button class="calitem" data-event="${e.id}">${fmt(e.start,{hour:'2-digit',minute:'2-digit'})} ${esc(e.title)}</button>`).join('')}${state.tasks.filter(t=>t.due&&localDate(t.due)===key).map(t=>`<button class="calitem task" data-task="${t.id}">${esc(t.title)}</button>`).join('')}</div>`}).join('')}</div></div>`}else{const from=new Date(d);from.setHours(0,0,0,0);if(view==='week')from.setDate(from.getDate()-from.getDay());const until=new Date(from);until.setDate(until.getDate()+(view==='week'?7:1));const es=expandedEvents(from,until);body=`<div class="panel">${Array.from({length:view==='week'?7:1},(_,i)=>{const day=new Date(from);day.setDate(day.getDate()+i);const key=day.toISOString().slice(0,10);return `<h3 class="section-title"><button class="day-create" data-newdate="${key}">${fmt(day,{weekday:'long',day:'2-digit',month:'long'})}<span>+ Compromisso</span></button></h3>${es.filter(e=>localDate(e.start)===key).map(e=>`<button class="row full" data-event="${e.id}"><strong>${fmt(e.start,{hour:'2-digit',minute:'2-digit'})}</strong><span class="grow">${esc(e.title)}</span><span class="tiny muted">${esc(e.location)}</span></button>`).join('')}${state.tasks.filter(t=>t.due&&localDate(t.due)===key).map(t=>`<button class="row full" data-task="${t.id}"><span class="pill">Tarefa</span><span>${esc(t.title)}</span></button>`).join('')}${!es.some(e=>localDate(e.start)===key)&&!state.tasks.some(t=>t.due&&localDate(t.due)===key)?empty('Sem compromissos ou prazos neste dia.'):''}`}).join('')}</div>`}return pagehead('Seu tempo, bem organizado.','Agenda e prazos integrados · horário de São Paulo.',`<button class="btn" data-action="newevent">${ic('plus')} Compromisso</button>`)+`<div class="filters"><button class="iconbtn" data-calnav="-1" aria-label="Anterior">‹</button><button class="btn secondary small" data-calnav="0">Hoje</button><button class="iconbtn" data-calnav="1" aria-label="Próximo">›</button><h2 style="margin:0 12px;text-transform:capitalize">${title}</h2><div class="viewtoggle">${[['month','Mês'],['week','Semana'],['day','Dia']].map(([v,n])=>`<button data-calview="${v}" class="${v===view?'selected':''}">${n}</button>`).join('')}</div></div>${body}`}
function roomName(r){return r.kind==='direct'?user(r.members.find(id=>id!==state.user.id)).name:r.name}
function chatsPage(){if(!state.rooms.some(r=>r.id===state.room))state.room=state.rooms[0]?.id;const r=state.rooms.find(r=>r.id===state.room);return pagehead('Conversas que conectam.','Combine entregas e mantenha a equipe por perto.',`<button class="btn" data-action="newroom">${ic('plus')} Nova conversa</button>`)+`<div class="chat-layout"><aside class="rooms">${state.rooms.map(r=>`<button class="room ${r.id===state.room?'active':''}" data-room="${r.id}"><span class="avatar">${r.kind==='direct'?esc(initials(roomName(r))):'#'}</span><div class="grow"><strong>${esc(roomName(r))}</strong><small>${esc(r.last?.text||'Comece a conversa')}</small></div>${r.unread?`<span class="unread">${r.unread}</span>`:''}</button>`).join('')}</aside><section class="conversation">${r?`<header class="conversation-head"><div><h3>${esc(roomName(r))}</h3><small>${r.members.length} participantes · Atualização em tempo real</small></div>${can('chat_manage')&&r.kind==='group'?`<button class="btn secondary small" id="editroom">Participantes</button>`:''}</header><div class="messages" id="messages">${empty('Carregando mensagens…')}</div><form class="composer" id="messageform"><button type="button" id="chatfile" class="iconbtn" aria-label="Anexar arquivo">${ic('paper')}</button><input name="text" required maxlength="5000" placeholder="Escreva uma mensagem…" autocomplete="off" aria-label="Mensagem"><button class="btn lime" type="submit" aria-label="Enviar mensagem">${ic('arrow')}</button></form>`:empty('Nenhuma conversa disponível.')}</section></div>`}
let messageSignature='';async function refreshMessages(force=false){if(state.page!=='chats'||!state.room||!$('#messages'))return;const selected=state.room;const r=await request('/rooms/'+selected+'/messages');if(state.room!==selected||!$('#messages'))return;const signature=JSON.stringify(r);if(signature===messageSignature&&!force)return;messageSignature=signature;const el=$('#messages'),atBottom=el.scrollHeight-el.scrollTop-el.clientHeight<100;const msgs=r.messages.map(m=>({...m,type:'text'})).concat(r.files.map(f=>({...f,type:'file'}))).sort((a,b)=>a.created.localeCompare(b.created));el.innerHTML=msgs.map(m=>`<div data-message-id="${esc(m.id)}" data-message-kind="${m.type==='text'?'message':'file'}" class="message ${m.user_id===state.user.id?'mine':''}"><span class="sender">${esc(m.name&&m.type==='text'?m.name:user(m.user_id).name)}</span><div class="bubble">${m.type==='text'?esc(m.text):`<a href="/files/${m.id}" target="_blank" rel="noopener">${ic('paper')} ${esc(m.name)} · Abrir arquivo</a>`}</div><small>${fmt(m.created)}</small></div>`).join('')||empty('Este é o começo da conversa.','Envie a primeira mensagem para a equipe.');if(atBottom||force)el.scrollTop=el.scrollHeight;await request('/rooms/'+selected+'/read',{method:'POST',data:{}})}
function teamPage(){return pagehead('Pessoas que fazem acontecer.','Perfis, responsabilidades e evolução das entregas.',can('user_manage')?`<button class="btn" data-action="newuser">${ic('plus')} Cadastrar usuário</button>`:'')+`<div class="notice">Indicadores dos últimos ${state.days} dias: tarefas criadas no período e atribuídas atualmente ao usuário. ${!state.user.master?'Os indicadores individuais estão disponíveis para o próprio usuário e para o master.':''}</div><div class="teamgrid">${state.users.map(u=>{const m=state.metrics.users.find(m=>m.id===u.id);return `<article class="personcard"><div style="display:flex;justify-content:space-between">${avatar(u,'big')}<span class="pill">${u.active?'Ativo':'Inativo'}</span></div><h3>${esc(u.name)}</h3><div class="tiny muted">${esc(u.title||'Função não definida')} · ${esc(u.area||'Área não definida')}</div><p class="bio">${esc(u.bio||'Descrição das responsabilidades ainda não cadastrada.')}</p>${m?`<div class="meter"><p><span>${m.done}/${m.total} tarefas resolvidas</span><strong>${m.percent}%</strong></p><div class="progress-track"><span style="--progress:${m.percent}%"></span></div><p>${m.pending} pendentes · ${m.progress} em andamento · ${m.approval} em aprovação</p><p>${m.late} tarefa(s) atrasada(s) no período</p></div>`:''}<div class="inline-actions" style="margin-top:20px">${can('audit')||u.id===state.user.id?`<button class="btn secondary small" data-activity="${u.id}">Histórico</button>`:''}${can('user_manage')||u.id===state.user.id?`<button class="btn secondary small" data-edituser="${u.id}">Editar perfil</button>`:''}${u.id!==state.user.id&&can('chats')&&u.active?`<button class="btn secondary small" data-direct="${u.id}">Conversar</button>`:''}</div></article>`}).join('')||empty('Nenhum usuário cadastrado.')}</div>`}
function notificationsPage(){return pagehead('Tudo o que precisa saber.','Acompanhe tarefas, compromissos e conversas.',`<button class="btn secondary" id="readall">Marcar todas como lidas</button>`)+`<div class="panel" style="padding:0">${state.notifications.map(n=>`<button class="noticerow full ${n.seen?'':'unseen'}" data-notice="${n.id}" style="text-align:left">${ic(n.category==='messages'?'chats':n.category==='events'?'calendar':'tasks')}<div><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small>${fmt(n.created)}</small></div></button>`).join('')||empty('Nenhuma notificação por enquanto.')}</div>`}
function settingsPage(){return pagehead('Do seu jeito.','Preferências, segurança e administração do sistema.')+`<div class="settingsgrid"><section class="panel"><h2>Seu perfil</h2><div class="row">${avatar(state.user,'big')}<div class="grow"><strong>${esc(state.user.name)}</strong><small>${esc(state.user.email)}</small></div><button class="btn secondary small" data-edituser="${state.user.id}">Editar</button></div><button class="btn secondary small" id="photobutton">Alterar foto</button><hr class="splitline"><h2>Segurança</h2><form id="passwordform">${field('Senha atual','current','password','',true)}${field('Nova senha','password','password','',true,'Mínimo 10 caracteres.')}<button class="btn" type="submit">Atualizar senha</button></form></section><section class="panel"><h2>Notificações e aplicativo</h2><p class="muted tiny">Receba alertas de acordo com suas preferências.</p><form id="prefsform">${[['tasks','Tarefas e prazos'],['events','Compromissos da agenda'],['messages','Mensagens do chat']].map(([k,n])=>`<label class="checkrow"><input type="checkbox" name="${k}" ${state.user.preferences[k]?'checked':''}>${n}</label>`).join('')}<button class="btn secondary small" style="margin-top:16px">Salvar preferências</button></form><hr class="splitline"><button class="btn" id="enablepush">${ic('notifications')} Ativar alertas neste dispositivo</button><p class="tiny muted" style="margin-top:12px">${state.push_key?'Push configurado no servidor.':'Push aguarda a configuração das chaves VAPID no servidor.'} A autorização também depende do navegador e do sistema operacional.</p><button class="btn secondary" data-action="install">Instalar no celular</button><p class="tiny muted" style="margin-top:12px">Offline: a tela de acesso e as instruções ficam disponíveis. Dados da equipe, mensagens e alterações exigem conexão.</p></section>${can('role_manage')?`<section class="panel"><div class="panelhead"><h2>Perfis de acesso</h2><button class="btn small" id="newrole">Novo perfil</button></div>${state.roles.map(r=>`<div class="row"><div class="grow"><strong>${esc(r.name)}</strong><small>${r.permissions.length} permissões</small></div>${r.id!=='master'?`<button class="btn secondary small" data-role="${r.id}">Editar</button>`:''}</div>`).join('')}</section>`:''}${can('audit')?`<section class="panel"><h2>Administração</h2><p class="tiny muted">Histórico de ações, acessos e alterações da equipe.</p><button class="btn secondary" id="auditbutton">Ver histórico de ações</button><hr class="splitline"><div class="notice">Recuperação por e-mail: ${state.smtp_ready?'configurada':'aguarda configuração SMTP'}. Backups são realizados pelo comando de manutenção, descrito no guia de instalação.</div></section>`:''}</div>`}
function bindContent(){bindTaskButtons();$$('[data-activity]').forEach(b=>b.onclick=async()=>{try{const rows=await request('/users/'+b.dataset.activity+'/activity');modal('Histórico de atividades',rows.map(r=>`<div class="row"><div><strong>${esc(r.action)}</strong><small>${fmt(r.created)} · ${esc(r.detail)}</small></div></div>`).join('')||empty('Nenhuma atividade registrada.'))}catch(e){toast(e.message)}});$$('[data-action]').forEach(b=>b.onclick=()=>({newtask:()=>taskForm(),newevent:()=>eventForm(),newuser:()=>userForm(),newroom:()=>roomForm(),install:installModal}[b.dataset.action]||(()=>{}))());$$('[data-event]').forEach(b=>b.onclick=()=>eventDetail(b.dataset.event));$$('[data-newdate]').forEach(b=>b.onclick=()=>eventForm(b.dataset.newdate));$$('[data-filter]').forEach(el=>el.addEventListener(el.tagName==='INPUT'?'input':'change',()=>{state.filters[el.dataset.filter]=el.value;$('#taskresults').innerHTML=taskResults();bindTaskButtons()}));$$('[data-view]').forEach(b=>b.onclick=()=>{state.taskView=b.dataset.view;renderContent()});$$('[data-calview]').forEach(b=>b.onclick=()=>{state.calView=b.dataset.calview;renderContent()});$$('[data-calnav]').forEach(b=>b.onclick=()=>{const n=+b.dataset.calnav;if(!n)state.calDate=new Date();else if(state.calView==='month')state.calDate=new Date(state.calDate.getFullYear(),state.calDate.getMonth()+n,1,12);else state.calDate.setDate(state.calDate.getDate()+n*(state.calView==='week'?7:1));renderContent()});$$('[data-edituser]').forEach(b=>b.onclick=()=>userForm(user(b.dataset.edituser)));$$('[data-direct]').forEach(b=>b.onclick=async()=>{try{const r=await request('/rooms',{method:'POST',data:{kind:'direct',members:[b.dataset.direct]}});await load();state.room=r.id;location.hash='chats:'+r.id}catch(e){toast(e.message)}});$$('[data-room]').forEach(b=>b.onclick=()=>{state.room=b.dataset.room;messageSignature='';renderContent()});if(state.page==='chats'){messageSignature='';refreshMessages(true).catch(e=>toast(e.message));$('#messageform')?.addEventListener('submit',async e=>{e.preventDefault();const inp=$('input',e.target),b=$('button[type=submit]',e.target);b.disabled=true;try{await request('/rooms/'+state.room+'/messages',{method:'POST',data:{text:inp.value,reply_to:e.target.dataset.replyTo||null,reply_kind:e.target.dataset.replyKind||'message'}});inp.value='';delete e.target.dataset.replyTo;delete e.target.dataset.replyKind;e.target.querySelector('.message-reply-draft')?.remove();await refreshMessages(true)}catch(e){toast(e.message)}finally{b.disabled=false}});$('#chatfile')?.addEventListener('click',()=>upload({room_id:state.room},()=>refreshMessages(true)));$('#editroom')?.addEventListener('click',()=>roomForm(state.rooms.find(r=>r.id===state.room)))}$('#metricdays')?.addEventListener('change',async e=>{state.days=+e.target.value;try{await load();renderContent()}catch(e){toast(e.message)}});$('#metricsearch')?.addEventListener('input',e=>{$('#metricrows').innerHTML=metricRows(state.metrics.users.filter(u=>(u.name+' '+u.area).toLowerCase().includes(e.target.value.toLowerCase())))});$('#readall')?.addEventListener('click',()=>mutate('/notifications/read','POST',{}));$$('[data-notice]').forEach(b=>b.onclick=async()=>{try{const n=state.notifications.find(n=>n.id===b.dataset.notice);await request('/notifications/read',{method:'POST',data:{id:n.id}});location.hash=n.link}catch(e){toast(e.message)}});$('#passwordform')?.addEventListener('submit',e=>{e.preventDefault();formSubmit(e.target,()=>request('/password',{method:'POST',data:Object.fromEntries(new FormData(e.target))}),()=>{e.target.reset();toast('Senha atualizada.')})});$('#prefsform')?.addEventListener('submit',e=>{e.preventDefault();formSubmit(e.target,()=>request('/preferences',{method:'POST',data:Object.fromEntries(['tasks','events','messages'].map(k=>[k,!!$('input[name='+k+']',e.target).checked]))}),async()=>{Object.assign(state,await request('/me'));toast('Preferências salvas.')})});$('#enablepush')?.addEventListener('click',enablePush);$('#photobutton')?.addEventListener('click',()=>upload({photo:true},async r=>{await request('/users/'+state.user.id,{method:'PATCH',data:{photo:r.id}});Object.assign(state,await request('/me'));await load();shell();toast('Foto atualizada.')}));$('#newrole')?.addEventListener('click',()=>roleForm());$$('[data-role]').forEach(b=>b.onclick=()=>roleForm(state.roles.find(r=>r.id===b.dataset.role)));$('#auditbutton')?.addEventListener('click',async()=>{try{const rows=await request('/audit');modal('Histórico de ações',rows.map(r=>`<div class="row"><div><strong>${esc(r.action)}</strong><small>${esc(r.name||'Sistema')} · ${fmt(r.created)}<br>${esc(r.detail)}</small></div></div>`).join('')||empty('Sem registros.'))}catch(e){toast(e.message)}})}
function bindTaskButtons(){$$('[data-task]').forEach(b=>b.onclick=()=>taskDetail(b.dataset.task).catch(e=>toast(e.message)));$$('[data-drag]').forEach(b=>b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.drag));$$('[data-drop]').forEach(el=>{el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(state.tasks.some(t=>t.id===id))mutate('/tasks/'+id,'PATCH',{status:el.dataset.drop})}})}
async function mutate(path,method,data){try{await request(path,{method,data});await load();renderContent();updateBadge();toast('Salvo no servidor.')}catch(e){toast(e.message)}}
let returnFocus;
function modal(title,body,wide=false){returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal ${wide?'wide':''}"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button id="closemodal" class="iconbtn" aria-label="Fechar">×</button></div>${body}</section></div>`;$('#closemodal').onclick=closeModal;$('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};$('#closemodal').focus();}
function closeModal(){$('#modal-root').innerHTML='';returnFocus?.focus()}
document.addEventListener('keydown',e=>{if(!$('#modal-root').children.length)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=$$('button,input,select,textarea,a[href]',$('#modal-root')).filter(x=>!x.disabled);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});
async function formSubmit(form,job,done){const b=$('button[type=submit]',form);if(b)b.disabled=true;let error=$('.form-error',form);if(error)error.textContent='';try{const result=await job();await done(result)}catch(e){if(error)error.textContent=e.message;else toast(e.message)}finally{if(b)b.disabled=false}}
function footer(label='Salvar'){return `<div class="form-error" role="alert"></div><div class="formfoot"><button type="button" class="btn secondary" data-cancel>Cancelar</button><button class="btn lime" type="submit">${label}</button></div>`}
function formBind(job,done){const form=$('#modalform');$('[data-cancel]',form).onclick=closeModal;form.onsubmit=e=>{e.preventDefault();formSubmit(form,()=>job(form),done||(async()=>{closeModal();await load();renderContent();toast('Salvo no servidor.')}))}}
function taskForm(t=null,parent=null){const owner=t?.owner||state.user.id;modal(t?'Editar tarefa':'Nova tarefa',`<form id="modalform"><div class="formgrid"><div class="span2">${field('Título da tarefa','title','text',t?.title||'',true)}</div><div class="span2">${textarea('Descrição','description',t?.description)}</div>${taskClientFields(t,parent)}${selectField('Prioridade','priority',Object.entries(priorityNames),t?.priority||'normal')}${selectField('Responsável','owner',(can('task_assign')?state.users.filter(u=>u.active):[state.user]).map(u=>[u.id,u.name]),owner)}${field('Início','start','datetime-local',inputDate(t?.start))}${field('Prazo','due','datetime-local',inputDate(t?.due))}${can('task_assign')?selectField('Participantes','members',state.users.filter(u=>u.active).map(u=>[u.id,u.name]),t?.members||[],true):''}</div>${footer(t?'Salvar alterações':'Criar tarefa')}</form>`);formBind(form=>{const d=Object.fromEntries(new FormData(form));d.start=datePayload(d.start);d.due=datePayload(d.due);if(can('task_assign'))d.members=new FormData(form).getAll('members');else{delete d.owner;if(!t)d.owner=state.user.id}if(parent)d.parent=parent;return request('/tasks'+(t?'/'+t.id:''),{method:t?'PATCH':'POST',data:d})})}
async function taskDetail(id){const t=await request('/tasks/'+id);modal(esc(t.title),`<div class="inline-actions"><span class="pill ${t.status}">${statusNames[t.status]}</span><span class="pill ${t.priority}">${priorityNames[t.priority]}</span>${late(t)?'<span class="pill late">Prazo vencido</span>':''}</div><p class="detail-description" style="margin-top:18px">${esc(t.description||'Sem descrição.')}</p><div class="row">${avatar(user(t.owner))}<div class="grow"><strong>${esc(user(t.owner).name)}</strong><small>${esc(t.project||'Sem projeto')} · Prazo: ${fmt(t.due)}</small></div>${can('task_edit')?'<button class="btn secondary small" id="edittask">Editar</button>':''}</div><div class="filters" style="margin-top:15px">${Object.entries(statusNames).filter(([s])=>s==='done'?can(t.status==='approval'?'task_approve':'task_complete'):can('task_edit')).map(([s,n])=>`<button class="btn ${s===t.status?'':'secondary'} small" data-status="${s}">${n}</button>`).join('')}</div><h3 class="section-title">Checklist</h3><div>${t.checklist.map((v,i)=>`<label class="checkrow"><input type="checkbox" data-check="${i}" ${v.done?'checked':''} ${can('task_edit')?'':'disabled'}>${esc(v.text)}</label>`).join('')||'<p class="tiny muted">Nenhum item.</p>'}</div>${can('task_edit')?'<form id="checkform" class="composer"><input name="item" required maxlength="300" placeholder="Adicionar item" aria-label="Novo item do checklist"><button class="btn secondary small">Adicionar</button></form>':''}<h3 class="section-title">Subtarefas</h3>${state.tasks.filter(x=>x.parent===id).map(x=>`<button class="row full" data-subtask="${x.id}">${esc(x.title)} <span class="pill ${x.status}">${statusNames[x.status]}</span></button>`).join('')}${can('task_create')?'<button class="btn secondary small" id="subtaskbutton">+ Criar subtarefa</button>':''}<h3 class="section-title">Materiais da tarefa</h3><div class="filelist">${t.files.map(f=>materialCard(f)).join('')||'<p class="tiny muted">Nenhum anexo.</p>'}</div>${can('task_edit')?'<button class="btn secondary small" id="taskfile">Enviar materiais</button>':''}<h3 class="section-title">Comentários</h3>${t.comments.map(c=>`<div class="comment"><small>${esc(c.name)} · ${fmt(c.created)}</small>${esc(c.text)}</div>`).join('')}<form id="commentform" class="composer comment-composer"><textarea name="text" rows="5" required maxlength="5000" placeholder="Escreva um comentário…" aria-label="Comentário"></textarea><button type="submit" class="btn">Enviar comentário</button></form><details style="margin-top:18px"><summary class="tiny muted">Histórico da tarefa</summary>${t.history.map(r=>`<p class="tiny muted">${esc(r.name)} · ${esc(r.action)} · ${fmt(r.created)}<br>${esc(r.detail)}</p>`).join('')}</details>`,true);
const save=async d=>{try{await request('/tasks/'+id,{method:'PATCH',data:d});await load();renderContent();await taskDetail(id)}catch(e){toast(e.message)}};$('#edittask')?.addEventListener('click',()=>taskForm(t));$$('[data-status]').forEach(b=>b.onclick=()=>save({status:b.dataset.status}));$$('[data-check]').forEach(el=>el.onchange=()=>{t.checklist[+el.dataset.check].done=el.checked;save({checklist:t.checklist})});$('#checkform')?.addEventListener('submit',e=>{e.preventDefault();t.checklist.push({text:$('input',e.target).value,done:false});save({checklist:t.checklist})});$('#commentform').onsubmit=e=>{e.preventDefault();formSubmit(e.target,()=>request('/tasks/'+id+'/comments',{method:'POST',data:{text:e.target.elements.text.value}}),()=>taskDetail(id))};$('#taskfile')?.addEventListener('click',()=>upload({task_id:id},()=>taskDetail(id)));$('#subtaskbutton')?.addEventListener('click',()=>taskForm(null,id));$$('[data-subtask]').forEach(b=>b.onclick=()=>taskDetail(b.dataset.subtask));}
function eventForm(day=today(),e=null){modal(e?'Editar compromisso':'Novo compromisso',`<form id="modalform"><div class="formgrid"><div class="span2">${field('Título','title','text',e?.title||'',true)}</div><div class="span2">${textarea('Descrição','description',e?.description)}</div>${field('Início','start','datetime-local',e?inputDate(e.start):day+'T09:00',true)}${field('Término','end','datetime-local',e?inputDate(e.end):day+'T10:00',true)}<div class="span2">${field('Local ou link da reunião','location','text',e?.location||'')}</div>${!e?selectField('Repetição','recurrence',[['none','Não repetir'],['daily','Diariamente'],['weekly','Semanalmente'],['monthly','Mensalmente']],'none')+field('Repetir até','until_date','datetime-local','',false,'Obrigatório para compromissos recorrentes.')+selectField('Lembrar antes','reminder',[['0','No horário'],['5','5 minutos'],['15','15 minutos'],['30','30 minutos'],['60','1 hora'],['1440','1 dia']],'30')+selectField('Participantes','members',state.users.filter(u=>u.active).map(u=>[u.id,u.name]),[],true)+(can('calendar_all')?'<label class="checkrow span2"><input type="checkbox" name="shared">Exibir na agenda compartilhada de toda a equipe</label>':''):''}</div>${footer(e?'Salvar alterações':'Criar compromisso')}</form>`);formBind(form=>{const d=Object.fromEntries(new FormData(form));d.start=datePayload(d.start);d.end=datePayload(d.end);if(!e){d.until_date=datePayload(d.until_date);d.members=new FormData(form).getAll('members');d.shared=!!d.shared}return request('/events'+(e?'/'+e.id:''),{method:e?'PATCH':'POST',data:d})})}
function eventDetail(id){const e=state.events.find(e=>e.id===id);if(!e)return;modal(esc(e.title),`<p class="detail-description">${esc(e.description||'Sem descrição.')}</p><div class="notice">${fmt(e.start)} — ${fmt(e.end)}<br>${esc(e.location||'Sem local definido')}<br>Recorrência: ${esc({none:'Não repete',daily:'Diária',weekly:'Semanal',monthly:'Mensal'}[e.recurrence])} · Lembrete ${e.reminder} min antes</div><h3>Participantes</h3>${e.members.map(m=>`<div class="row">${avatar(user(m))}<strong>${esc(user(m).name)}</strong></div>`).join('')}${can('calendar_all')||e.creator===state.user.id?'<div class="formfoot"><button class="btn danger" id="deleteevent">Cancelar compromisso</button><button class="btn" id="editevent">Editar</button></div>':''}`);$('#editevent')?.addEventListener('click',()=>eventForm(today(),e));$('#deleteevent')?.addEventListener('click',async()=>{try{await request('/events/'+id,{method:'DELETE',data:{}});closeModal();await load();renderContent();toast('Compromisso cancelado.')}catch(e){toast(e.message)}})}
function userForm(u=null){const admin=can('user_manage');modal(u?'Editar perfil':'Cadastrar usuário',`<form id="modalform"><div class="formgrid"><div class="span2">${field('Nome completo','name','text',u?.name||'',true)}</div>${!u?field('E-mail de acesso','email','email','',true):''}${admin?field(u?'Nova senha (deixe em branco para manter)':'Senha inicial','password','password','',!u,'Mínimo 10 caracteres.'):''}${field('Cargo / função','title','text',u?.title||'')}${field('Área de atuação','area','text',u?.area||'')}<div class="span2">${textarea('Descrição das responsabilidades','bio',u?.bio)}</div>${admin&&!u?.master?selectField('Perfil de acesso','role_id',state.roles.filter(r=>r.id!=='master').map(r=>[r.id,r.name]),u?.role_id||'member'):''}${admin&&u&&!u.master?`<label class="checkrow"><input type="checkbox" name="active" ${u.active?'checked':''}>Usuário ativo</label>`:''}</div>${footer(u?'Salvar perfil':'Cadastrar usuário')}</form>`);formBind(form=>{const d=Object.fromEntries(new FormData(form));if(u&&admin&&!u.master)d.active=!!d.active;return request('/users'+(u?'/'+u.id:''),{method:u?'PATCH':'POST',data:d})},async()=>{if(u?.id===state.user.id)Object.assign(state,await request('/me'));closeModal();await load();shell();toast('Perfil salvo.')})}
function roomForm(r=null){modal(r?'Administrar grupo':'Nova conversa',`<form id="modalform">${!r?selectField('Tipo de conversa','kind',can('chat_manage')?[['direct','Individual'],['group','Grupo']]:[['direct','Individual']],'direct'):''}${field('Nome do grupo','name','text',r?.name||'')}${selectField('Participantes','members',state.users.filter(u=>u.active&&u.id!==state.user.id).map(u=>[u.id,u.name]),r?.members||[],true)}<p class="tiny muted">Conversa individual: selecione uma pessoa. Grupo: selecione os integrantes desejados. Você participa automaticamente.</p>${footer(r?'Salvar participantes':'Criar conversa')}</form>`);let selected;formBind(async form=>{const d=Object.fromEntries(new FormData(form));d.members=new FormData(form).getAll('members');const res=await request('/rooms'+(r?'/'+r.id:''),{method:r?'PATCH':'POST',data:d});selected=r?.id||res.id},async()=>{closeModal();await load();state.room=selected;location.hash='chats:'+selected;route()})}
const permLabels={dashboard:'Painel e indicadores',tasks:'Acessar tarefas',calendar:'Acessar calendário',chats:'Acessar chats',team:'Ver equipe',notifications:'Ver notificações',task_create:'Criar tarefas',task_edit:'Editar tarefas acessíveis',task_assign:'Atribuir responsáveis',task_approve:'Aprovar tarefas',task_complete:'Concluir tarefas',task_all:'Ver todas as tarefas',calendar_all:'Gerenciar toda a agenda',user_manage:'Administrar usuários',role_manage:'Administrar permissões',chat_manage:'Administrar grupos',audit:'Ver auditoria'};
function roleForm(r=null){modal('Perfil de acesso',`<form id="modalform">${field('Nome do perfil','name','text',r?.name||'',true)}<div class="notice">Permissões administrativas concedem controle sobre outros usuários. Marque apenas as funções necessárias.</div><div class="permissions">${Object.entries(permLabels).map(([k,n])=>`<label><input type="checkbox" name="permissions" value="${k}" ${r?.permissions.includes(k)?'checked':''}>${n}</label>`).join('')}</div>${footer()}</form>`);formBind(form=>request('/roles',{method:'POST',data:{id:r?.id,name:new FormData(form).get('name'),permissions:new FormData(form).getAll('permissions')}}))}
async function upload(destination,callback){const input=document.createElement('input');input.type='file';input.accept=(destination.photo||destination.room_photo)?'image/png,image/jpeg,image/webp':'image/png,image/jpeg,image/webp,application/pdf';input.onchange=async()=>{const f=input.files[0];if(!f)return;if(f.size>8*1024*1024){toast('Limite de arquivo: 8 MB.');return}try{toast('Enviando arquivo…');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});const result=await request('/upload',{method:'POST',data:{...destination,name:f.name,data}});await callback(result);toast('Arquivo recebido pelo servidor.')}catch(e){toast(e.message)}};input.click()}
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
function installModal(){modal('NJA System no seu celular',`<div class="notice">A instalação no celular exige um endereço HTTPS. O acesso local é destinado aos testes no computador.</div><h3>Android</h3><p>Abra no Chrome e use o menu → “Instalar aplicativo” ou “Adicionar à tela inicial”.</p>${installPrompt?'<button class="btn lime" id="install-now">Instalar agora</button>':''}<h3>iPhone</h3><p>Abra no Safari, toque em Compartilhar → “Adicionar à Tela de Início” e abra o aplicativo pelo novo ícone.</p><h3>Alertas</h3><p>Depois da instalação, abra Configurações no sistema e toque em “Ativar alertas neste dispositivo”. No iPhone, push requer iOS 16.4 ou posterior e o aplicativo instalado na Tela de Início.</p><p class="tiny muted">Entrega sujeita à conexão, permissões e configurações de foco/economia de energia. Offline: sem envio de alterações nem mensagens. Nenhum dado sensível é armazenado no cache offline.</p>`);$('#install-now')?.addEventListener('click',async()=>{await installPrompt.prompt();installPrompt=null;closeModal()})}
async function enablePush(){try{if(!state.push_key)throw Error('O administrador precisa configurar as chaves VAPID e o processo de alertas no servidor.');if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window))throw Error('Push não está disponível aqui. No iPhone, instale o app na Tela de Início e abra por lá.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notificações não autorizadas. Verifique as permissões do navegador.');const reg=await navigator.serviceWorker.ready;const key=state.push_key.replace(/-/g,'+').replace(/_/g,'/');const bytes=Uint8Array.from(atob(key+'='.repeat((4-key.length%4)%4)),c=>c.charCodeAt(0));const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});await request('/push',{method:'POST',data:{subscription:sub.toJSON()}});toast('Este dispositivo está cadastrado para receber alertas.')}catch(e){toast(e.message)}}
function network(){const offline=!navigator.onLine;$('#offline').hidden=!offline;if(!offline&&state.user)load().then(()=>{if(!$('#modal-root').children.length)renderContent()}).catch(()=>{})}window.addEventListener('online',network);window.addEventListener('offline',network);$('#offline').hidden=navigator.onLine;
if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});
// NJA System — conversas e perfis, versão 1.1.
const originalBindContent=bindContent, originalTeamPage=teamPage, originalRoomForm=roomForm;
let chatFilter='',chatUnreadOnly=false,chatDetails=false,chatFiles=[];
function roomAvatar(r){return r.kind==='direct'?avatar(user(r.members.find(id=>id!==state.user.id))):r.photo?`<img class="avatar" src="/files/${esc(r.photo)}" alt="${esc(r.name)}">`:`<span class="avatar">${esc(initials(r.name))}</span>`}
chatsPage=function(){if(!state.rooms.some(r=>r.id===state.room))state.room=state.rooms[0]?.id;const r=state.rooms.find(r=>r.id===state.room);return pagehead('Conversas que conectam.','Sua equipe e seus clientes, em um só lugar.',`<button class="btn" data-action="newroom">${ic('plus')} Nova conversa</button>`)+`<div class="chat-layout ${chatDetails?'with-details':''}"><aside class="rooms"><div class="room-tools"><input id="chatsearch" placeholder="Buscar conversa ou cliente" aria-label="Buscar conversa" value="${esc(chatFilter)}"><div class="viewtoggle"><button id="chatall" class="${!chatUnreadOnly?'selected':''}">Todas</button><button id="chatunread" class="${chatUnreadOnly?'selected':''}">Não lidas</button></div></div><div id="roomlist">${roomList()}</div></aside><section class="conversation">${r?`<header class="conversation-head">${roomAvatar(r)}<div class="grow"><h3>${esc(roomName(r))}</h3><small>${r.members.length} participantes${r.project?' · '+esc(r.project):''}</small></div><button class="iconbtn" id="chatinfo" title="Informações da conversa" aria-label="Informações da conversa">${ic('team')}</button></header><div class="messages" id="messages">${empty('Carregando mensagens…')}</div><form class="composer" id="messageform"><button type="button" id="chatfile" class="iconbtn" aria-label="Anexar arquivo">${ic('paper')}</button><input name="text" required maxlength="5000" placeholder="Escreva uma mensagem…" autocomplete="off" aria-label="Mensagem"><button class="btn lime" type="submit" aria-label="Enviar mensagem">${ic('arrow')}</button></form>`:empty('Nenhuma conversa disponível.')}</section>${r&&chatDetails?`<aside class="chat-details" id="chat-details">${roomDetails(r)}</aside>`:''}</div>`};
function roomList(){return state.rooms.filter(r=>(!chatUnreadOnly||r.unread>0)&&(!chatFilter||(roomName(r)+' '+(r.project||'')).toLowerCase().includes(chatFilter.toLowerCase()))).map(r=>`<button class="room ${r.id===state.room?'active':''}" data-room="${r.id}">${roomAvatar(r)}<div class="grow"><strong>${esc(roomName(r))}</strong><small>${esc(r.last?.text||r.description||'Comece a conversa')}</small></div><div class="room-meta">${r.last?`<small>${fmt(r.last.created,{hour:'2-digit',minute:'2-digit'})}</small>`:''}${r.unread?`<span class="unread">${r.unread}</span>`:''}</div></button>`).join('')||empty('Nenhuma conversa encontrada.')}
function roomDetails(r){const linked=state.tasks.filter(t=>r.client_id?t.client_id===r.client_id:r.project&&t.project===r.project);return `<header class="panelhead"><h3>Sobre a conversa</h3><button id="closedetails" class="iconbtn" aria-label="Fechar informações">×</button></header><div class="room-identity">${roomAvatar(r)}<h3>${esc(roomName(r))}</h3><p class="tiny muted">${esc(r.description||'')}</p>${r.project?`<span class="pill">${esc(r.project)}</span>`:''}${can('chat_manage')&&r.kind==='group'?'<div class="inline-actions"><button class="btn secondary small" id="editroom">Editar grupo</button><button class="btn secondary small" id="roomphoto">Alterar imagem</button></div>':''}</div><h4>Participantes · ${r.members.length}</h4>${r.members.map(id=>`<button class="row full profile-link" data-profile="${esc(id)}">${avatar(user(id))}<div class="grow"><strong>${esc(user(id).name)}</strong><small>${esc(user(id).title||'Colaborador')}</small></div></button>`).join('')}<h4>Arquivos e imagens</h4><div id="room-media">${mediaHTML()}</div><h4>Tarefas do projeto</h4>${linked.map(t=>`<button class="row full" data-task="${esc(t.id)}"><div class="grow"><strong>${esc(t.title)}</strong><small>${statusNames[t.status]}</small></div></button>`).join('')||empty(r.project?'Nenhuma tarefa visível neste projeto.':'Vincule um projeto para exibir suas tarefas.')}<h4>Links compartilhados</h4><div id="room-links"></div>`}
function mediaHTML(){return chatFiles.map(f=>`<a class="media-item" href="/files/${esc(f.id)}" target="_blank" rel="noopener">${f.mime.startsWith('image/')?`<img src="/files/${esc(f.id)}" alt="${esc(f.name)}" loading="lazy">`:ic('paper')}<span>${esc(f.name)}</span></a>`).join('')||empty('Nenhum arquivo compartilhado.')}
refreshMessages=async function(force=false){if(state.page!=='chats'||!state.room||!$('#messages'))return;const selected=state.room;const r=await request('/rooms/'+selected+'/messages');if(state.room!==selected||!$('#messages'))return;const signature=JSON.stringify(r);chatFiles=r.files;if(signature===messageSignature&&!force)return;messageSignature=signature;const el=$('#messages'),atBottom=el.scrollHeight-el.scrollTop-el.clientHeight<100;const msgs=r.messages.map(m=>({...m,type:'text'})).concat(r.files.map(f=>({...f,type:'file'}))).sort((a,b)=>a.created.localeCompare(b.created));el.innerHTML=msgs.map(m=>`<div data-message-id="${esc(m.id)}" data-message-kind="${m.type==='text'?'message':'file'}" class="message ${m.user_id===state.user.id?'mine':''}"><button class="sender profile-link" data-profile="${esc(m.user_id)}">${esc(user(m.user_id).name)}</button><div class="bubble">${m.type==='text'?esc(m.text):`<a href="/files/${esc(m.id)}" target="_blank" rel="noopener">${m.mime.startsWith('image/')?`<img class="message-image" src="/files/${esc(m.id)}" alt="${esc(m.name)}" loading="lazy">`:ic('paper')}${esc(m.name)}</a>`}</div><small>${fmt(m.created)}</small></div>`).join('')||empty('Este é o começo da conversa.','Envie a primeira mensagem para a equipe.');bindProfileLinks(el);if(atBottom||force)el.scrollTop=el.scrollHeight;if($('#room-media'))$('#room-media').innerHTML=mediaHTML();const links=[...new Set(r.messages.flatMap(m=>m.text.match(/https?:\/\/[^\s<>"']+/g)||[]))];if($('#room-links'))$('#room-links').innerHTML=links.map(url=>`<a class="media-item" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a>`).join('')||empty('Nenhum link compartilhado.');await request('/rooms/'+selected+'/read',{method:'POST',data:{}});const room=state.rooms.find(x=>x.id===selected);if(room)room.unread=0;};
function bindProfileLinks(root=document){$$('[data-profile]',root).forEach(b=>b.onclick=()=>profilePanel(b.dataset.profile))}
function bindChatDetails(){const r=state.rooms.find(r=>r.id===state.room);$('#closedetails')?.addEventListener('click',()=>{chatDetails=false;renderContent()});$('#editroom')?.addEventListener('click',()=>roomForm(r));$('#roomphoto')?.addEventListener('click',()=>upload({room_id:r.id,room_photo:true},async()=>{await load();renderContent()}));bindProfileLinks();bindTaskButtons();}
bindContent=function(){originalBindContent();bindProfileLinks();if(state.page==='chats'){chatFiles=[];$('#chatinfo')?.addEventListener('click',()=>{chatDetails=!chatDetails;renderContent()});$('#chatsearch')?.addEventListener('input',e=>{chatFilter=e.target.value;$('#roomlist').innerHTML=roomList();bindRoomList()});$('#chatall')?.addEventListener('click',()=>{chatUnreadOnly=false;renderContent()});$('#chatunread')?.addEventListener('click',()=>{chatUnreadOnly=true;renderContent()});bindChatDetails();}$$('[data-cover]').forEach(b=>b.onclick=()=>upload({photo:true},async r=>{await request('/users/'+state.user.id,{method:'PATCH',data:{cover:r.id}});Object.assign(state,await request('/me'));await load();shell()}));};
function bindRoomList(){$$('[data-room]').forEach(b=>b.onclick=()=>{state.room=b.dataset.room;chatFiles=[];messageSignature='';renderContent()})}
teamPage=function(){let html=originalTeamPage();html=html.replace(/<article class="personcard">/g,'<article class="personcard social-card">');state.users.forEach(u=>{html=html.replace(`<h3>${esc(u.name)}</h3>`,`<button class="profile-link" data-profile="${esc(u.id)}"><h3>${esc(u.name)}</h3></button>`);html=html.replace(`${avatar(u,'big')}<span class="pill">`,`${u.cover?`<img class="person-cover" src="/files/${esc(u.cover)}" alt="">`:''}${avatar(u,'big')}<span class="pill">`)});return html};
const originalSettingsPage=settingsPage;settingsPage=function(){return originalSettingsPage().replace('Alterar foto</button>','Alterar foto</button> <button class="btn secondary small" data-cover="true">Alterar capa</button>')};
roomForm=function(r=null){originalRoomForm(r);const form=$('#modalform');const fieldset=document.createElement('div');fieldset.innerHTML=field('Cliente / projeto','project','text',r?.project||'')+textarea('Descrição do grupo','description',r?.description||'');const hint=$('p',form);form.insertBefore(fieldset,hint);};
function profilePanel(id,tab='info'){const u=user(id);const m=state.metrics.users.find(x=>x.id===id);const tasks=state.tasks.filter(t=>t.owner===id);const events=state.events.filter(e=>e.creator===id||e.members.includes(id));const content=tab==='tasks'?tasks.map(t=>`<button class="row full" data-task="${esc(t.id)}"><div class="grow"><strong>${esc(t.title)}</strong><small>${esc(t.project||'Geral')} · ${statusNames[t.status]} · ${fmt(t.due)}</small></div></button>`).join('')||empty('Nenhuma tarefa visível.'):tab==='calendar'?events.map(e=>`<button class="row full" data-profile-event="${esc(e.id)}"><div><strong>${esc(e.title)}</strong><small>${fmt(e.start)}</small></div></button>`).join('')||empty('Nenhum compromisso visível.'):tab==='activity'?'<div id="profile-activity">Carregando atividades…</div>':`<section class="panel"><h3>Sobre ${esc(u.name.split(' ')[0])}</h3><p class="detail-description">${esc(u.bio||'Responsabilidades ainda não cadastradas.')}</p><div class="profile-info"><div><small>Cargo / função</small><strong>${esc(u.title||'Não definido')}</strong></div><div><small>Área de atuação</small><strong>${esc(u.area||'Não definida')}</strong></div><div><small>E-mail</small><strong>${esc(u.email)}</strong></div><div><small>Na equipe desde</small><strong>${fmt(u.created,{day:'2-digit',month:'long',year:'numeric'})}</strong></div></div></section>${m?`<section class="panel"><h3>Entregas · últimos ${state.days} dias</h3>${metricRows([m])}<p class="tiny muted">${esc(state.metrics.criterion)}</p></section>`:''}`;
modal(esc(u.name),`<div class="profile-cover" ${u.cover?`style="background-image:url('/files/${esc(u.cover)}')"`:''}></div><div class="profile-header">${avatar(u,'big')}<div class="grow"><h2>${esc(u.name)}</h2><p>${esc(u.title||'Colaborador')} · ${esc(u.area||'NJA')}</p></div><span class="pill">${u.active?'Ativo':'Inativo'}</span></div><div class="profile-actions">${id!==state.user.id&&can('chats')&&u.active?'<button class="btn" id="profile-chat">Conversar</button>':''}${can('user_manage')||id===state.user.id?'<button class="btn secondary" id="profile-edit">Editar perfil</button>':''}${id===state.user.id?'<button class="btn secondary" id="profile-cover">Alterar capa</button> <button class="btn secondary" id="profile-photo">Alterar foto</button>':''}</div><div class="profile-tabs">${[['info','Perfil'],['tasks','Tarefas'],['calendar','Calendário'],...(can('audit')||id===state.user.id?[['activity','Atividades']]:[])].map(([key,label])=>`<button data-profile-tab="${key}" class="${tab===key?'selected':''}">${label}</button>`).join('')}</div><div class="profile-body">${content}<p class="tiny muted">Tarefas e compromissos exibidos conforme suas permissões.</p></div>`,true);
$$('[data-profile-tab]').forEach(b=>b.onclick=()=>profilePanel(id,b.dataset.profileTab));bindTaskButtons();$$('[data-profile-event]').forEach(b=>b.onclick=()=>eventDetail(b.dataset.profileEvent));$('#profile-edit')?.addEventListener('click',()=>userForm(u));$('#profile-chat')?.addEventListener('click',async()=>{try{const r=await request('/rooms',{method:'POST',data:{kind:'direct',members:[id]}});closeModal();await load();state.room=r.id;location.hash='chats:'+r.id;}catch(e){toast(e.message)}});for(const key of ['cover','photo'])$('#profile-'+key)?.addEventListener('click',()=>upload({photo:true},async r=>{await request('/users/'+id,{method:'PATCH',data:{[key]:r.id}});Object.assign(state,await request('/me'));await load();profilePanel(id)}));if(tab==='activity')request('/users/'+id+'/activity').then(rows=>{if($('#profile-activity'))$('#profile-activity').innerHTML=rows.map(r=>`<div class="row"><div><strong>${esc(r.action)}</strong><small>${fmt(r.created)} · ${esc(r.detail)}</small></div></div>`).join('')||empty('Nenhuma atividade registrada.')}).catch(e=>{if($('#profile-activity'))$('#profile-activity').textContent=e.message});}

const originalLoginScreen=loginScreen;
loginScreen=function(mode='login'){
 originalLoginScreen(mode);const reset=new URLSearchParams(location.search).get('reset');if(reset)mode='reset';const form=$('#loginform');const stage=document.createElement('div');stage.className='ninja-login';stage.innerHTML=`<div class="login-scene" aria-hidden="true"><div class="scene-grid"></div><div class="scene-glow"></div><img class="throwing-ninja" src="/ninja-throw.png" alt="">${[0,1,2].map(i=>`<div class="flying-star star-${i}"><svg viewBox="0 0 100 100"><defs><linearGradient id="metal-${i}" x2="1" y2="1"><stop stop-color="#e8fcff"/><stop offset=".5" stop-color="#39a3d8"/><stop offset="1" stop-color="#113b67"/></linearGradient></defs><path fill="url(#metal-${i})" stroke="#84eaff" stroke-width="2" d="M50 3 59 35 96 50 65 59 50 97 41 65 4 50 35 41Z"/><circle cx="50" cy="50" r="7" fill="#071224" stroke="#92e6ff" stroke-width="2"/></svg></div>`).join('')}</div><header class="login-brand">${brand()}</header><div class="login-tagline"><span class="label">SEU TIME. SUA MISSÃO.</span><h1>Organize.<br>Conecte.<br><em>Conquiste.</em></h1><p>O espaço de trabalho da equipe NJA.</p></div><section class="login-access"><div class="login-card"></div><div class="login-mobile-note">Seu sistema, também no celular.<br>Instale pelo navegador após acessar.</div></section><footer class="login-footer">${developed()}<span>Acesso exclusivo da equipe NJA</span></footer>`;$('#app').replaceChildren(stage);$('.login-card').append(form);$('h2',form).textContent=mode==='login'?'Entre no NJA System':mode==='recover'?'Recupere seu acesso':'Crie uma nova senha';$('.label',form).textContent='SISTEMA DO NINJA';const p=$('p',form);p.textContent=mode==='login'?'Sua equipe conectada, suas entregas organizadas.':p.textContent;
 if(mode==='login'){const email=$('[name=email]',form),password=$('[name=password]',form),passLabel=password.closest('label'),forgot=$('#forgot'),submit=$('[type=submit]',form),oldSubmit=form.onsubmit;let step=1;passLabel.hidden=true;password.disabled=true;forgot.hidden=true;submit.innerHTML=`Continuar ${ic('arrow')}`;const identity=document.createElement('button');identity.type='button';identity.className='login-identity';identity.hidden=true;passLabel.before(identity);identity.onclick=()=>{step=1;email.closest('label').hidden=false;passLabel.hidden=true;password.disabled=true;forgot.hidden=true;identity.hidden=true;submit.innerHTML=`Continuar ${ic('arrow')}`;email.focus()};form.onsubmit=async e=>{e.preventDefault();if(step===1){if(!email.reportValidity())return;step=2;email.closest('label').hidden=true;passLabel.hidden=false;password.disabled=false;password.autocomplete='current-password';forgot.hidden=false;identity.textContent=email.value+' · Alterar';identity.hidden=false;submit.innerHTML=`Entrar no sistema ${ic('arrow')}`;password.focus();return}await oldSubmit(e)};const toggle=document.createElement('button');toggle.type='button';toggle.className='show-password';toggle.textContent='Mostrar senha';toggle.onclick=()=>{password.type=password.type==='password'?'text':'password';toggle.textContent=password.type==='password'?'Mostrar senha':'Ocultar senha'};passLabel.append(toggle);}
};


